  --accent: rgb(26, 24, 19);
  --accent-foreground: rgb(247, 245, 238);
  --destructive: rgb(241, 68, 68);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(62, 62, 56);
  --input: rgb(81, 80, 74);
  --ring: rgb(27, 126, 222);
  --chart-1: rgb(178, 87, 47);
  --chart-2: rgb(156, 135, 246);
  --chart-3: rgb(26, 24, 19);
  --chart-4: rgb(48, 44, 72);
